<?php
/**
 * Plugin Name: NESPORTS3 Updater V58 (Dynamic Story Image Hotfix)
 * Description: Ensures dashboard image selection takes 100% priority over Elementor cached post meta, wipes old filter conflicts, and keeps live site perfectly reactive.
 * Version: 58.0
 * Author: NESports
 */

if (!defined('ABSPATH')) exit;

function run_nesports_v58_sync() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store',
        WP_PLUGIN_DIR . '/nesports-custom'
    );
    if (is_dir(WP_PLUGIN_DIR)) {
        $files = scandir(WP_PLUGIN_DIR);
        foreach ($files as $f) {
            if ($f === '.' || $f === '..') continue;
            if (stripos($f, 'nesport') !== false) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }

    $payloads = array(
        'includes/helpers.php' => base64_decode(''),
        'includes/class-nesports-admin.php' => base64_decode(''),
        'includes/elementor-widgets/widget-story.php' => base64_decode(''),
        'templates/page-story.php' => base64_decode(''),
        'templates/page-contact.php' => base64_decode(''),
        'templates/header-nesports.php' => base64_decode(''),
        'templates/footer-nesports.php' => base64_decode(''),
        'assets/css/nesports-admin.css' => base64_decode(''),

    );

    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }

    // 1. Deactivate ALL old updater/patch plugins in database option
    $active = get_option('active_plugins', array());
    if (is_array($active)) {
        $clean_active = array();
        foreach ($active as $p) {
            if (stripos($p, 'updater-v') !== false || stripos($p, 'nesports-patch') !== false) {
                continue; // strip out old updaters
            }
            $clean_active[] = $p;
        }
        update_option('active_plugins', $clean_active);
    }

    // 2. Physically neutralize any lingering updater files that force logo/filters
    if (is_dir(WP_PLUGIN_DIR)) {
        foreach (scandir(WP_PLUGIN_DIR) as $dir) {
            if ($dir === '.' || $dir === '..') continue;
            if (stripos($dir, 'updater-v54') !== false || stripos($dir, 'updater-v55') !== false) {
                $pdir = WP_PLUGIN_DIR . '/' . $dir;
                if (is_dir($pdir)) {
                    foreach (glob($pdir . '/*.php') as $f) {
                        @file_put_contents($f, "<?php // Deactivated permanently
");
                    }
                }
            }
        }
    }

    // 3. Clear Elementor Cache & sync post 30090
    $settings = get_option('nesports_store_settings', array());
    if (is_array($settings) && !empty($settings['about_feature_img'])) {
        $img = $settings['about_feature_img'];
        $post_id = 30090;
        $meta = get_post_meta($post_id, '_elementor_data', true);
        if (!empty($meta)) {
            $decoded = json_decode($meta, true);
            if (is_array($decoded)) {
                array_walk_recursive($decoded, function(&$item, $key) use ($img) {
                    if ($key === 'url' && (strpos($item, 'WhatsApp-Image') !== false || strpos($item, 'logo.png') !== false || strpos($item, 'uploads') !== false)) {
                        $item = $img;
                    }
                });
                update_post_meta($post_id, '_elementor_data', wp_slash(json_encode($decoded)));
            }
        }
    }

    if (class_exists('\Elementor\Plugin')) {
        \Elementor\Plugin::$instance->files_manager->clear_cache();
    }

    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v58']) && $_GET['nesports_apply_v58'] === '1') {
        $res = run_nesports_v58_sync();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
    run_nesports_v58_sync();
}, 1);

register_activation_hook(__FILE__, 'run_nesports_v58_sync');
